package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.view.*;
final class SettingsUi {
 static void run(Instrumentation t){Context c=t.getTargetContext();try{c.getSharedPreferences("network_route",0).edit().putBoolean("local_dpi",false).commit();Activity a=t.startActivitySync(new Intent(c,AppSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MotionUi.stage(t,"DPI_OFF");t.runOnMainSync(()->{Switch s=find(a.getWindow().getDecorView(),"Дробление TLS ClientHello");s.performClick();});Thread.sleep(700);MotionUi.stage(t,"DPI_ON");t.runOnMainSync(()->{ScrollView scroll=scroll(a.getWindow().getDecorView());scroll.fullScroll(View.FOCUS_DOWN);});Thread.sleep(700);MotionUi.stage(t,"CONTINUITY_SETTINGS");t.runOnMainSync(a::finish);t.finish(Activity.RESULT_OK,new Bundle());}catch(Throwable e){Bundle b=new Bundle();b.putString("failure",e.toString());t.finish(Activity.RESULT_CANCELED,b);}finally{c.getSharedPreferences("network_route",0).edit().putBoolean("local_dpi",false).commit();}}
 static Switch find(View v,String s){if(v instanceof Switch&&((Switch)v).getText().toString().equals(s))return (Switch)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Switch r=find(((ViewGroup)v).getChildAt(i),s);if(r!=null)return r;}return null;}
 static ScrollView scroll(View v){if(v instanceof ScrollView)return (ScrollView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){ScrollView r=scroll(((ViewGroup)v).getChildAt(i));if(r!=null)return r;}return null;}
}
